CREATE DATABASE IF NOT EXISTS nexusid_university CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE nexusid_university;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS access_logs,event_registrations,events,maintenance_requests,library_issues,library_books,parent_links,merchant_order_items,merchant_orders,merchant_products,merchant_outlets,transactions,wallets,notifications,results,timetable,student_subjects,faculty_subjects,subjects,classrooms,biometric_profiles,attendance,users,merchants,departments,fee_payments,fee_invoices;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(20),password_hash VARCHAR(255) NOT NULL,role ENUM('STUDENT','FACULTY','HOD','ADMIN','PARENT','SECURITY','MERCHANT') NOT NULL,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,code VARCHAR(20) UNIQUE NOT NULL);
CREATE TABLE subjects(id BIGINT AUTO_INCREMENT PRIMARY KEY,department_id BIGINT,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,credits INT DEFAULT 3,semester INT NOT NULL,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE classrooms(id BIGINT AUTO_INCREMENT PRIMARY KEY,room_no VARCHAR(30) UNIQUE NOT NULL,building VARCHAR(100),capacity INT);
CREATE TABLE student_subjects(student_id BIGINT,subject_id BIGINT,semester INT NOT NULL,status ENUM('ENROLLED','DROPPED') DEFAULT 'ENROLLED',PRIMARY KEY(student_id,subject_id),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE faculty_subjects(faculty_id BIGINT,subject_id BIGINT,PRIMARY KEY(faculty_id,subject_id),FOREIGN KEY(faculty_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE timetable(id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_id BIGINT NOT NULL,classroom_id BIGINT,day_name ENUM('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(classroom_id) REFERENCES classrooms(id));
CREATE TABLE results(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,marks DECIMAL(5,2),grade VARCHAR(5),exam_name VARCHAR(100),UNIQUE(student_id,subject_id,exam_name),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE attendance(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,class_date DATE NOT NULL,status ENUM('PRESENT','ABSENT','LATE') NOT NULL,method ENUM('MANUAL','FACE','PALM') DEFAULT 'MANUAL',UNIQUE(student_id,subject_id,class_date),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE biometric_profiles(user_id BIGINT PRIMARY KEY,face_template MEDIUMTEXT,palm_template MEDIUMTEXT,face_enabled BOOLEAN DEFAULT FALSE,palm_enabled BOOLEAN DEFAULT FALSE,liveness_enabled BOOLEAN DEFAULT FALSE,status ENUM('ACTIVE','DISABLED') DEFAULT 'ACTIVE',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wallets(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL,balance DECIMAL(12,2) DEFAULT 0,daily_spend_limit DECIMAL(12,2) DEFAULT 5000,status ENUM('ACTIVE','BLOCKED') DEFAULT 'ACTIVE',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE merchants(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL,merchant_name VARCHAR(150) NOT NULL,business_type VARCHAR(100),status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE merchant_outlets(id BIGINT AUTO_INCREMENT PRIMARY KEY,merchant_id BIGINT NOT NULL,name VARCHAR(150) NOT NULL,business_type VARCHAR(100),location VARCHAR(150),status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',UNIQUE(merchant_id,name),FOREIGN KEY(merchant_id) REFERENCES merchants(id) ON DELETE CASCADE);
CREATE TABLE merchant_products(id BIGINT AUTO_INCREMENT PRIMARY KEY,outlet_id BIGINT NOT NULL,name VARCHAR(150) NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT DEFAULT 0,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',FOREIGN KEY(outlet_id) REFERENCES merchant_outlets(id) ON DELETE CASCADE);
CREATE TABLE merchant_orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,payer_user_id BIGINT NOT NULL,merchant_id BIGINT NOT NULL,total_amount DECIMAL(12,2) NOT NULL,status ENUM('PAID','PROCESSING','READY','COLLECTED','CANCELLED','REFUNDED') DEFAULT 'PAID',reference_id VARCHAR(100) UNIQUE NOT NULL,note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(payer_user_id) REFERENCES users(id),FOREIGN KEY(merchant_id) REFERENCES merchants(id));
CREATE TABLE merchant_order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES merchant_orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES merchant_products(id));
CREATE TABLE transactions(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,transaction_type ENUM('DEBIT','CREDIT') NOT NULL,description VARCHAR(255),reference_id VARCHAR(100),related_user_id BIGINT,payment_method VARCHAR(50),status ENUM('SUCCESS','FAILED') DEFAULT 'SUCCESS',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(150),message VARCHAR(500),is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE parent_links(parent_user_id BIGINT NOT NULL,student_id BIGINT NOT NULL,PRIMARY KEY(parent_user_id,student_id),UNIQUE KEY uq_parent_links_student(student_id),FOREIGN KEY(parent_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE library_books(id BIGINT AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(40) UNIQUE,name VARCHAR(200) NOT NULL,author VARCHAR(150),category VARCHAR(100),total_copies INT DEFAULT 1,available_copies INT DEFAULT 1,status ENUM('AVAILABLE','INACTIVE') DEFAULT 'AVAILABLE');
CREATE TABLE library_issues(id BIGINT AUTO_INCREMENT PRIMARY KEY,book_id BIGINT NOT NULL,user_id BIGINT NOT NULL,issued_at DATETIME DEFAULT CURRENT_TIMESTAMP,due_at DATE NOT NULL,returned_at DATETIME,status ENUM('ISSUED','RETURNED','OVERDUE') DEFAULT 'ISSUED',FOREIGN KEY(book_id) REFERENCES library_books(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE events(id BIGINT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description VARCHAR(500),event_date DATE NOT NULL,location VARCHAR(150),capacity INT DEFAULT 100,status ENUM('OPEN','CLOSED','CANCELLED') DEFAULT 'OPEN');
CREATE TABLE event_registrations(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(event_id,user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE maintenance_requests(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,category VARCHAR(80),description VARCHAR(500),location VARCHAR(150),status ENUM('OPEN','IN_PROGRESS','RESOLVED','CANCELLED') DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE maintenance_status_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id BIGINT NOT NULL,changed_by BIGINT NOT NULL,old_status VARCHAR(20) NULL,new_status VARCHAR(20) NOT NULL,note VARCHAR(500) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_maintenance_history_request(request_id),INDEX idx_maintenance_history_changed_at(changed_at),FOREIGN KEY(request_id) REFERENCES maintenance_requests(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE access_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,method ENUM('CARD','FACE','PALM','MANUAL') NOT NULL,entry_type ENUM('ENTRY','EXIT') NOT NULL,location VARCHAR(150),status ENUM('GRANTED','DENIED') DEFAULT 'GRANTED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE fee_invoices(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id BIGINT NOT NULL,title VARCHAR(150),amount DECIMAL(12,2) NOT NULL,due_date DATE,status ENUM('PENDING','PAID','CANCELLED') DEFAULT 'PENDING',FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE fee_payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT NOT NULL,student_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,reference_id VARCHAR(100) UNIQUE,paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES fee_invoices(id),FOREIGN KEY(student_id) REFERENCES users(id));

